    WHERE WorkflowCode = 'DEMO_P_FLOW';

    -- 3. Update StepsWorkflow transitions Data column (NotificationId and MailId)
    
    -- SUBMIT_TO_TS (FO -> TS) -> Notif: 11 (Initial), Mail: Initiated
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 11), '$.mailTemplateId', @InitiatedId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_TO_TS' AND FromNodeId = 'FO' AND ToNodeId = 'TS';

    -- SUBMIT_TO_PM (TS -> PM) -> Notif: 6 (PolicyIssuance), Mail: NULL
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 6), '$.mailTemplateId', NULL)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_TO_PM' AND FromNodeId = 'TS' AND ToNodeId = 'PM';

    -- SUBMIT_FOLLOWUP (PM -> FO) -> Notif: 6 (PolicyIssuance), Mail: FollowUp
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 6), '$.mailTemplateId', @FollowUpId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_FOLLOWUP' AND FromNodeId = 'PM' AND ToNodeId = 'FO';

    -- SUBMIT_FOLLOWUP (PM -> TS) -> Notif: 6 (PolicyIssuance), Mail: FollowUp
