    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 6), '$.mailTemplateId', @FollowUpId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_FOLLOWUP' AND FromNodeId = 'PM' AND ToNodeId = 'TS';

    -- SUBMIT_NO_FOLLOWUP (PM -> End) -> Notif: 9 (Success), Mail: NULL
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 9), '$.mailTemplateId', NULL)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_NO_FOLLOWUP' AND FromNodeId = 'PM' AND ToNodeId = 'End';

    -- FO_SUBMIT_PM (FO -> PM) -> Notif: 6 (PolicyIssuance), Mail: Signed
