    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 6), '$.mailTemplateId', @SignedId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'FO_SUBMIT_PM' AND FromNodeId = 'FO' AND ToNodeId = 'PM';

    -- TS_SUBMIT_PM (TS -> PM) -> Notif: 6 (PolicyIssuance), Mail: PreComplete
