    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 6), '$.mailTemplateId', @PreCompleteId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'TS_SUBMIT_PM' AND FromNodeId = 'TS' AND ToNodeId = 'PM';

    -- COMPLETE (PM -> End) -> Notif: 9 (Success), Mail: NULL
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(JSON_MODIFY(ISNULL(Data, '{}'), '$.notificationTemplateId', 9), '$.mailTemplateId', NULL)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'COMPLETE' AND FromNodeId = 'PM' AND ToNodeId = 'End';

    COMMIT TRANSACTION;
    PRINT 'Transaction committed successfully. DEMO_P_FLOW notifications & mails updated! âœ…';
END TRY
BEGIN CATCH
